def forward(groups):
    day, month, year, hour, minute, second, tz_offset = groups
    month_map = {'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6, 'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12}
    dt = datetime(int(year), month_map[month], int(day), int(hour), int(minute), int(second))
    tz_delta = int(tz_offset[:3]) * 3600 + int(tz_offset[3:]) * 60
    micros = int((dt.timestamp() - tz_delta) * 1000000)
    return {'stored': [micros], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    tz_offset_hours = int(dt.utcoffset().total_seconds() / 3600)
    tz_offset_minutes = int((dt.utcoffset().total_seconds() % 3600) / 60)
    tz_offset = f'{tz_offset_hours:+03}{tz_offset_minutes:02}'
    return dt.strftime(f'[%d/%b/%Y:%H:%M:%S {tz_offset}]')

